    'faqp.q1':           '\u041a\u0430\u043a \u043f\u0440\u043e\u0434\u0430\u0442\u044c \u0441\u043a\u0438\u043d\u044b \u043d\u0430 SKINSELL?',
    'faqp.a1':           '\u0412\u043e\u0439\u0434\u0438\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 Steam, \u043f\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0443 \u043f\u0440\u043e\u0434\u0430\u0436\u0438, \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u044b, \u0432\u0432\u0435\u0434\u0438\u0442\u0435 Trade URL, \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043f\u043e\u0441\u043e\u0431 \u043e\u043f\u043b\u0430\u0442\u044b \u0438 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 "\u041f\u043e\u043b\u0443\u0447\u0438\u0442\u044c \u043e\u043f\u043b\u0430\u0442\u0443". \u041d\u0430\u0448 \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440 \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442 \u0432\u0430\u043c \u0442\u0440\u0435\u0439\u0434-\u043e\u0444\u0444\u0435\u0440 \u2014 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f \u0438 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432 \u0432\u044b\u043f\u043b\u0430\u0442\u0430 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f.',
    'faqp.q2':           '\u041a\u0430\u043a\u0438\u0435 \u0438\u0433\u0440\u044b \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f?',
    'faqp.a2':           '\u041c\u044b \u043f\u043e\u043a\u0443\u043f\u0430\u0435\u043c \u0441\u043a\u0438\u043d\u044b \u0438\u0437 Counter-Strike 2, Dota 2, Team Fortress 2 \u0438 Rust. \u0412 \u0431\u0443\u0434\u0443\u0449\u0435\u043c \u043c\u043e\u0433\u0443\u0442 \u0431\u044b\u0442\u044c \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u044b \u0434\u0440\u0443\u0433\u0438\u0435 \u0438\u0433\u0440\u044b.',
