    'faqp.a3':           '\u0414\u043b\u044f \u0441\u043a\u0438\u043d\u043e\u0432 Dota 2, TF2 \u0438 Rust \u2014 \u0432\u044b\u043f\u043b\u0430\u0442\u0430 \u043e\u0431\u0440\u0430\u0431\u0430\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432\u0441\u043a\u043e\u0440\u0435 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u0438\u044f \u043f\u0440\u0435\u0434\u043c\u0435\u0442\u043e\u0432. \u0414\u043b\u044f CS2 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0442\u0440\u0435\u0439\u0434-\u0445\u043e\u043b\u0434. \u041e\u043f\u043b\u0430\u0442\u0430 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f \u0445\u043e\u043b\u0434\u0430.',
    'faqp.q4':           '\u0427\u0442\u043e \u0442\u0430\u043a\u043e\u0435 \u0431\u0430\u043b\u0430\u043d\u0441 \u0441\u0430\u0439\u0442\u0430?',
