const CURRENCY = {
  USD: { symbol: '$', rate: 1,     pos: 'after' },
  EUR: { symbol: '\u20ac', rate: 0.92,  pos: 'after' },
  RUB: { symbol: '\u20bd', rate: 92,    pos: 'after' },
};

function applyLang(lang) {
  if (!I18N[lang]) return;
  localStorage.setItem('sw_lang', lang);
  const dict = I18N[lang];

  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (dict[key] !== undefined) el.textContent = dict[key];
  });

  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    if (dict[key] !== undefined) el.innerHTML = dict[key];
  });

  document.querySelectorAll('[data-i18n-ph]').forEach(el => {
    const key = el.getAttribute('data-i18n-ph');
    if (dict[key] !== undefined) el.setAttribute('placeholder', dict[key]);
  });

  document.querySelectorAll('[data-i18n-title]').forEach(el => {
    const key = el.getAttribute('data-i18n-title');
    if (dict[key] !== undefined) el.setAttribute('title', dict[key]);
  });

  const chipSpan = document.querySelector('#langChip span');
  if (chipSpan) chipSpan.textContent = lang;
  document.querySelectorAll('.header__dropdown-wrap').forEach(w => {
    const chip = w.querySelector('#langChip');
    if (!chip) return;
    w.querySelectorAll('.header__dropdown-item').forEach(it => {
      it.classList.toggle('is-active', it.dataset.val === lang);
    });
  });
}

function applyCurrency(cur) {
  const c = CURRENCY[cur];
  if (!c) return;
  localStorage.setItem('sw_currency', cur);

  document.querySelectorAll('[data-price-usd]').forEach(el => {
    const usd = parseFloat(el.getAttribute('data-price-usd'));
    if (isNaN(usd)) return;
    const converted = (usd * c.rate).toFixed(2);
    el.textContent = converted + c.symbol;
  });

  const chipSpan = document.querySelector('#currencyChip span');
  if (chipSpan) chipSpan.textContent = cur;
  document.querySelectorAll('.header__dropdown-wrap').forEach(w => {
    const chip = w.querySelector('#currencyChip');
    if (!chip) return;
    w.querySelectorAll('.header__dropdown-item').forEach(it => {
      it.classList.toggle('is-active', it.dataset.val === cur);
    });
  });
}

function initI18n() {
  const lang = localStorage.getItem('sw_lang') || 'EN';
  const cur  = localStorage.getItem('sw_currency') || 'USD';
  applyLang(lang);
  applyCurrency(cur);
}
